//! OS UDP applications. Echo replies are generated by the endpoint kernel.
use crate::{
    IO, Result, STARTUP, request,
    signals::{Role, Signal, Signals},
};
use meshway_configuration::NodeAddresses;
use std::{
    net::{IpAddr, Ipv4Addr, Ipv6Addr, SocketAddr},
    time::Duration,
};
use tokio::{net::UdpSocket, sync::watch};

pub const SENTINELS: [&[u8]; 2] = [
    b"Meshway-real-kernel-IPv4-UDP-nativeTCP-opaque-relay-sentinel-",
    b"Meshway-real-kernel-IPv6-UDP-nativeTCP-opaque-relay-sentinel-",
];

pub struct Applications {
    ipv4: UdpSocket,
    ipv6: UdpSocket,
}
impl Applications {
    pub async fn bind(role: Role, own: &NodeAddresses) -> Result<Self> {
        let port = if role == Role::B { 42424 } else { 0 };
        let v4 = own.ipv4.ok_or("missing own IPv4")?;
        let v6 = own.ipv6.ok_or("missing own IPv6")?;
        let ipv4 = UdpSocket::bind(SocketAddr::new(v4.into(), port)).await?;
        // Binding the actual assigned address proves DAD has completed. No
        // fixed sleep, sysctl change or optimistic/freebind option is used.
        let ipv6 = tokio::time::timeout(STARTUP, async {
            loop {
                match UdpSocket::bind(SocketAddr::new(v6.into(), port)).await {
                    Ok(socket) => return Ok::<_, crate::Error>(socket),
                    Err(error) if error.kind() == std::io::ErrorKind::AddrNotAvailable => {
                        tokio::time::sleep(Duration::from_millis(50)).await
                    }
                    Err(error) => return Err(error.into()),
                }
            }
        })
        .await??;
        Ok(Self { ipv4, ipv6 })
    }

    pub async fn run(
        self,
        role: Role,
        peer: NodeAddresses,
        signals: Signals,
        mut stopped: watch::Receiver<bool>,
    ) -> Result<()> {
        let shutdown = stopped.clone();
        tokio::select! {
            _ = stopped.changed() => Ok(()),
            result = self.active(role, peer, signals, shutdown) => result,
        }
    }

    async fn active(
        self,
        role: Role,
        peer: NodeAddresses,
        signals: Signals,
        mut stopped: watch::Receiver<bool>,
    ) -> Result<()> {
        signals
            .write(&format!("ready-{}", role.name()), Signal::Ready { role })
            .await?;
        match role {
            Role::A => {
                let Signal::Ready { role: Role::B } = signals.wait("ready-b").await? else {
                    return Err("invalid endpoint readiness".into());
                };
                let destination4 = IpAddr::V4(peer.ipv4.ok_or("missing remote IPv4")?);
                let destination6 = IpAddr::V6(peer.ipv6.ok_or("missing remote IPv6")?);
                for (index, (socket, destination)) in
                    [(&self.ipv4, destination4), (&self.ipv6, destination6)]
                        .into_iter()
                        .enumerate()
                {
                    let mut payload = SENTINELS[index].to_vec();
                    payload.extend_from_slice(request()?.to_string().as_bytes());
                    socket.connect(SocketAddr::new(destination, 42424)).await?;
                    let sent = tokio::time::timeout(IO, socket.send(&payload)).await??;
                    if sent != payload.len() {
                        return Err("short OS UDP send".into());
                    }
                    let mut response = [0; 512];
                    let received = tokio::time::timeout(IO, socket.recv(&mut response)).await??;
                    if response[..received] != payload {
                        return Err("application echo mismatch".into());
                    }
                    tracing::info!(
                        family = if index == 0 { "ipv4" } else { "ipv6" },
                        phase = "application-echo",
                        bytes = received,
                        "OS UDP application verified"
                    );
                }
                signals.write("done", Signal::Done).await?;
                Ok(())
            }
            Role::B => {
                let (a, b) = tokio::join!(
                    echo(&self.ipv4, SENTINELS[0], &peer, stopped.clone()),
                    echo(&self.ipv6, SENTINELS[1], &peer, stopped.clone()),
                );
                a?;
                b?;
                Ok(())
            }
            Role::R => {
                let _ = stopped.changed().await;
                Err("relay must never create endpoint applications".into())
            }
        }
    }
}

async fn echo(
    socket: &UdpSocket,
    sentinel: &[u8],
    peer: &NodeAddresses,
    mut stopped: watch::Receiver<bool>,
) -> Result<()> {
    let mut buffer = [0; 512];
    loop {
        tokio::select! {
            _ = stopped.changed() => return Ok(()),
            received = socket.recv_from(&mut buffer) => {
                let (length, address) = received?;
                let expected = match address.ip() { IpAddr::V4(value) => peer.ipv4 == Some(value), IpAddr::V6(value) => peer.ipv6 == Some(value) };
                if !expected || !buffer[..length].starts_with(sentinel) { return Err("unexpected application datagram".into()); }
                let sent = tokio::time::timeout(IO, socket.send_to(&buffer[..length], address)).await??;
                if sent != length { return Err("short OS echo send".into()); }
            }
        }
    }
}

pub fn prefixes(own: &NodeAddresses, peer: &NodeAddresses) -> Result<(Ipv4Addr, u8, Ipv6Addr, u8)> {
    let (v4, other4) = (
        own.ipv4.ok_or("missing own IPv4")?,
        peer.ipv4.ok_or("missing peer IPv4")?,
    );
    let (v6, other6) = (
        own.ipv6.ok_or("missing own IPv6")?,
        peer.ipv6.ok_or("missing peer IPv6")?,
    );
    let mut prefix4 = (u32::from(v4) ^ u32::from(other4)).leading_zeros().min(30);
    let prefix6 = (u128::from(v6) ^ u128::from(other6)).leading_zeros();
    if v4 == other4
        || v6 == other6
        || (u32::from(v4) >> 22) != (u32::from(Ipv4Addr::new(100, 64, 0, 0)) >> 22)
        || prefix4 < 10
        || v6.octets()[0] & 0xfe != 0xfc
        || prefix6 < 7
    {
        return Err("fixture endpoints need distinct CGNAT/ULA addresses".into());
    }
    // The selected connected subnet must not turn the remote endpoint into a
    // subnet broadcast/network address (e.g. allocated .1 and .3 under /30).
    while prefix4 >= 10 {
        let mask = u32::MAX >> prefix4;
        if [v4, other4].iter().all(|address| {
            let host = u32::from(*address) & mask;
            host != 0 && host != mask
        }) {
            break;
        }
        prefix4 -= 1;
    }
    if prefix4 < 10 {
        return Err("fixture needs non-broadcast endpoint addresses".into());
    }
    Ok((
        v4,
        u8::try_from(prefix4)?,
        v6,
        u8::try_from(prefix6.min(64))?,
    ))
}
